/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_user`, `record_id`,
         `operation_date`, `table_description`, `operation_status`)
    VALUES
        ('tb_people', 'Create', USER(),
         IF(NEW.person_ID <= 4294967295, NEW.person_ID, NULL),
         CURRENT_TIMESTAMP,
         CONCAT('Nueva persona: person_ID=', NEW.person_ID,
                ', user_ID=', COALESCE(CAST(NEW.user_ID AS CHAR), 'NULL'),
                ', given_names=', NEW.given_names,
                ', family_names=', COALESCE(NEW.family_names, 'NULL')),
         b'1');
END */;;
