/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_categories_insert` AFTER INSERT ON `tbd_products_categories` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        record_id,
        operation_date,
        table_description,
        operation_status
    )
    VALUES (
        'tbd_products_categories',
        'Create',
        CURRENT_USER(),
        NEW.product_Id,
        NOW(),
        CONCAT(
            'Se creó la relación producto: ',
            NEW.product_Id,
            ' con categoría: ',
            NEW.category_Id,
            '. Status: ',
            IF(NEW.status = b'1', 'Activo', 'Inactivo')
        ),
        b'1'
    );
END */;;
